const event = $input.first().json.event || $input.first().json;
const payload = event.payload || {};

const systemPrompt = `Eres el gestor de tareas de RAX.\nTu misión es proponer compromisos accionables y medibles para el plan de mentoría.\nREGLAS:\n1. No dupliques compromisos ya existentes en la lista de tareas activas.\n2. Cada tarea debe tener un criterio de finalización tangible (successCriteria) y la evidencia que se requerirá (evidenceRequired).\n3. Si una tarea depende de otra o tiene bloqueos evidentes, indícalo.\n4. Salida en JSON estricto con: suggestedTasks (array de objetos con title, description, ownerSuggestion, dueDateSuggestion, successCriteria, evidenceRequired, relatedGoalId), uncertainties (array de strings).`;

const userPrompt = JSON.stringify({
  projectId: event.projectId,
  goals: payload.goals || [],
  existingTasks: payload.existingTasks || [],
  contextSource: payload.contextSource || 'session'
});

return [{
  json: {
    correlationId: event.correlationId || 'corr_' + Date.now(),
    callbackUrl: event.callback?.url || ($env.RAX_API_URL || 'http://localhost:3000') + '/api/n8n/callback',
    model: $env.OPENROUTER_MODEL || 'meta-llama/llama-3.3-70b-instruct:free',
    apiKey: $env.OPENROUTER_API_KEY || '',
    systemPrompt,
    userPrompt
  }
}];

const response = $input.first().json;
const prep = $('Build Task Proposals Prompt').first().json;

let parsed = {};
try {
  const content = response.choices?.[0]?.message?.content || '{}';
  parsed = JSON.parse(content);
} catch (e) {
  parsed = { suggestedTasks: [], uncertainties: ['Salida JSON no válida'] };
}

const proposals = (parsed.suggestedTasks || []).map(t => ({
  type: 'task',
  title: t.title,
  description: t.description || '',
  ownerSuggestion: t.ownerSuggestion || undefined,
  dueDateSuggestion: t.dueDateSuggestion || undefined,
  successCriteria: t.successCriteria || undefined,
  evidenceRequired: t.evidenceRequired || undefined,
  needsHumanApproval: true,
  uncertainties: []
}));

const callbackPayload = {
  operationId: 'op_tsk_' + Date.now(),
  correlationId: prep.correlationId,
  workflowId: 'RAX-08',
  workflowVersion: '1.0.0',
  status: 'completed',
  usage: {
    model: response.model || prep.model,
    promptTokens: response.usage?.prompt_tokens || 0,
    completionTokens: response.usage?.completion_tokens || 0
  },
  data: {
    summary: `Se propusieron ${proposals.length} tareas para revisión.`,
    proposals,
    uncertainties: parsed.uncertainties || []
  }
};

return [{
  json: {
    callbackUrl: prep.callbackUrl,
    payload: callbackPayload
  }
}];
